namespace RonSijm.FluidHumidifier.Factories.IdentityStore;

public class UserFactory(string resourceName = null, Action<Humidifier.IdentityStore.User> factoryAction = null) : ResourceFactory<Humidifier.IdentityStore.User>(resourceName)
{

    internal List<InnerUserPhoneNumbersItemsFactory> PhoneNumbersFactories { get; set; } = [];

    internal List<InnerUserRolesItemsFactory> RolesFactories { get; set; } = [];

    internal List<InnerUserAddressesItemsFactory> AddressesFactories { get; set; } = [];

    internal List<InnerUserPhotosItemsFactory> PhotosFactories { get; set; } = [];

    internal List<InnerUserEmailsItemsFactory> EmailsFactories { get; set; } = [];

    internal InnerUserNameFactory NameFactory { get; set; }

    protected override Humidifier.IdentityStore.User Create()
    {
        var userResult = CreateUser();
        factoryAction?.Invoke(userResult);

        return userResult;
    }

    private Humidifier.IdentityStore.User CreateUser()
    {
        var userResult = new Humidifier.IdentityStore.User
        {
            GivenName = InputResourceName,
        };

        return userResult;
    }
    public override void CreateChildren(Humidifier.IdentityStore.User result)
    {
        base.CreateChildren(result);

        result.PhoneNumbers = PhoneNumbersFactories.Any() ? PhoneNumbersFactories.Select(x => x.Build()).ToList() : null;
        result.Roles = RolesFactories.Any() ? RolesFactories.Select(x => x.Build()).ToList() : null;
        result.Addresses = AddressesFactories.Any() ? AddressesFactories.Select(x => x.Build()).ToList() : null;
        result.Photos = PhotosFactories.Any() ? PhotosFactories.Select(x => x.Build()).ToList() : null;
        result.Emails = EmailsFactories.Any() ? EmailsFactories.Select(x => x.Build()).ToList() : null;
        result.Name ??= NameFactory?.Build();
    }

} // End Of Class

